function loadDeepClone() {
  const mod = require(path.resolve(__dirname, '../../../../src/options/clone'));

  // Direct function export
  if (typeof mod === 'function') return mod;

  // Common module shapes
  if (typeof mod?.default === 'function') return mod.default;
  if (typeof mod?.deepCloneObject === 'function') return mod.deepCloneObject;
  if (typeof mod?.clone === 'function') return mod.clone;

