const path = require('path');

let deepCloneObject;

function loadDeepClone() {
  const mod = require(path.resolve(__dirname, '../../../../src/options/clone'));
  if (typeof mod === 'function') return mod;
  if (typeof mod?.default === 'function') return mod.default;
  if (typeof mod?.deepCloneObject === 'function') return mod.deepCloneObject;
  throw new Error('deepCloneObject function not found in module');
}

beforeAll(() => {
  deepCloneObject = loadDeepClone();
});

describe('deepCloneObject', () => {
  test('clones primitive values and preserves own keys and symbol keys', () => {
    const sym = Symbol('sym');
    const obj = {
      a: 1,
      b: 'str',
      c: true
    };
    obj[sym] = 123;

    const clone = deepCloneObject(obj);

    expect(clone).not.toBe(obj);
    expect(clone.a).toBe(1);
    expect(clone.b).toBe('str');
    expect(clone.c).toBe(true);
    expect(clone[sym]).toBe(123);

    expect(Reflect.ownKeys(clone)).toContain('a');
    expect(Reflect.ownKeys(clone)).toContain(sym);

    // Ensure symbol property exists but is not enumerable
    expect(Object.keys(clone)).not.toContain(sym);
  });

  test('copies non-enumerable properties with preserved descriptors', () => {
    const obj = {};
    Object.defineProperty(obj, 'hidden', {
      value: 42,
      enumerable: false,
      writable: true,
      configurable: true
    });
    Object.defineProperty(obj, 'visible', {
      value: 5,
      enumerable: true,
      writable: true,
      configurable: true
    });

    const clone = deepCloneObject(obj);

    const descHidden = Object.getOwnPropertyDescriptor(clone, 'hidden');
    expect(descHidden).toBeDefined();
    expect(descHidden.enumerable).toBe(false);
    expect(clone.hidden).toBe(42);

    expect(clone.visible).toBe(5);
    expect(Object.keys(clone)).toContain('visible');
    expect(Object.keys(clone)).not.toContain('hidden');
  });

  test('clones nested objects through deepClone on values', () => {
    const inner = { x: 1 };
    const obj = { outer: inner };
    const clone = deepCloneObject(obj);

    expect(clone).not.toBe(obj);
    expect(clone.outer).not.toBe(inner);
    expect(clone.outer.x).toBe(1);
  });

