    const proto = { inherited: 9 };
    const obj = Object.create(proto);
    obj.ownProp = 7;

    const clone = deepCloneObject(obj);

    expect(clone).toHaveProperty('ownProp', 7);
    expect(clone).not.toHaveProperty('inherited');
  });
});

