  if (!isErrorInstance(error.cause)) {
    return mergeErrorCause(error)
  }

  error.wrap = isSubclass(error.cause.constructor, ErrorClass)

  if (!shouldPrefixCause(error, ErrorClass)) {
    return mergeErrorCause(error)
  }

  return mergePrefixedError(error)
}

